def b_bump_go(es: List<&2, HEntry>, +pos: Nat, +skip: Nat, +w: Nat) -> List<&2, HEntry>:
  match es:
    case Nil{}:
      Nil{}
    case Con{e, t}:
      match e:
        case HEntry{+ver, +tot, +n, +hb, +prev, +post, +lbn, +csr, +bvh, +tag, +bdo, +bdf, +bdn, +bds}:
          Con{ite(HEntry, Bool.and(Nat.is_gt(pos, 0n), Bool.not(Nat.is_eq(pos, skip))), HEntry{ver, tot, n, hb, prev, post, lbn, csr, bvh, tag, bdo, Nat.add(bdf, w), bdn, bds}, HEntry{ver, tot, n, hb, prev, post, lbn, csr, bvh, tag, bdo, bdf, bdn, bds}), b_bump_go(t, 1n+pos, skip, w)}

def b_bump_f(es: List<&2, HEntry>, skip: Nat, w: Nat) -> List<&2, HEntry>:
  b_bump_go(es, 0n, skip, w)

def b_any_go(cs: List<&2, HCh>, +i: Nat, +lo: Nat, +hi: Nat) -> Bool:
  match cs:
    case Nil{}:
      False{}
    case Con{c, t}:
      match c:
        case HCh{cc, cd, cs0, cw, cf}:
          Bool.or(Bool.and(Bool.and(Nat.is_ge(i, lo), Nat.is_le(i, hi)), Bool.and(Bool.not(Nat.is_eq(cc, 0n)), Bool.not(cf))), b_any_go(t, 1n+i, lo, hi))

def b_any_open(cs: List<&2, HCh>, lo: Nat, hi: Nat) -> Bool:
  b_any_go(cs, 0n, lo, hi)

def b_clear_go(cs: List<&2, HCh>, +i: Nat, +lo: Nat, +hi: Nat) -> List<&2, HCh>:
  match cs:
    case Nil{}:
      Nil{}
    case Con{c, t}:
      Con{ite(HCh, Bool.and(Nat.is_ge(i, lo), Nat.is_le(i, hi)), empty_ch(), c), b_clear_go(t, 1n+i, lo, hi)}

def b_clear_chs(cs: List<&2, HCh>, lo: Nat, hi: Nat) -> List<&2, HCh>:
  b_clear_go(cs, 0n, lo, hi)

def b_zero_csr(es: List<&2, HEntry>) -> List<&2, HEntry>:
  match es:
    case Nil{}:
      Nil{}
    case Con{e, t}:
      match e:
        case HEntry{ver, tot, n, hb, prev, post, lbn, csr, bvh, tag, bdo, bdf, bdn, bds}:
          Con{HEntry{ver, tot, n, hb, prev, post, lbn, 0n, bvh, tag, bdo, bdf, bdn, bds}, b_zero_csr(t)}
